    public String abbreviateProduct(int left, int right) {
        long twos = 0, fives = 0;
        for (int i = left; i <= right; i++) {
            int temp = i;
            while (temp % 2 == 0) {
                twos++;
                temp /= 2;
            }
            temp = i;
            while (temp % 5 == 0) {
                fives++;
                temp /= 5;
            }
        }
        long zeros = Math.min(twos, fives);
        long rem2 = twos - zeros;
        long rem5 = fives - zeros;

        double exactLog10 = 0;
        for (int i = left; i <= right; i++) {
            exactLog10 += Math.log10(i);
        }
        long totalDigits = (long) Math.floor(exactLog10) + 1;

        long t2 = rem2, t5 = rem5;
        double prodPrefix = 1.0;
        long prodSuffix = 1;
        boolean overflow = false;
        long MOD = 10000000000L; // 10 digits

        for (int i = left; i <= right; i++) {
            long val = i;
            while (t2 > 0 && val % 2 == 0) {
                val /= 2;
                t2--;
            }
            while (t5 > 0 && val % 5 == 0) {
                val /= 5;
                t5--;
            }
            prodSuffix = prodSuffix * val;
            if (prodSuffix >= MOD) {
                overflow = true;
                prodSuffix %= MOD;
            }

            prodPrefix *= i;
            while (prodPrefix >= 100000.0) {
                prodPrefix /= 10.0;
            }
