        }

        if (totalDigits <= 10) {
            // Recompute exact product without removing 2s and 5s
            long exact = 1;
            for (int i = left; i <= right; i++) {
                exact *= i;
            }
            return exact + "e" + zeros;
        } else {
            // Get first 5 digits from prodPrefix
            // prodPrefix is something like 12345.678
            // We want 5 digits.
            // Let's compute prefix more carefully.
            double logProd = 0;
            for (int i = left; i <= right; i++) {
                logProd += Math.log10(i);
            }
            // first digit is at logProd - floor(logProd)
            double firstFew = Math.pow(10, logProd - Math.floor(logProd) + 4);
            long prefix = (long) firstFew; // 5 digits

            // Wait, let's use the loop prodPrefix directly or log-based.
            // Actually, `prodPrefix` after dividing by 10 whenever >= 100000 might have lost precision if we do it step by step.
