            long first5 = (long) Math.floor(Math.pow(10, (exactLog10 - Math.floor(exactLog10)) + 4));

            // Format suffix to 5 digits with leading zeros
            String suffixStr = String.format("%05d", prodSuffix % 100000);

            return first5 + "..." + suffixStr + "e" + zeros;
